```sql
with med_inc AS (
    select cbsa_code, median_income, year FROM doorstep.mart_metro_year WHERE year = 2023 ORDER BY median_income DESC LIMIT 5 
)
select * FROM med_inc;

let t1 = 
  SELECT month AS label, sum(balance) as value FROM ledger.extract_deposits_monthly WHERE year = 2024 AND quarter = '02' GROUP BY period ORDER BY label
let t2 = 
  SELECT month AS label, sum(balance) as value FROM ledger.extract_deposits_monthly WHERE year = 2025 AND quarter = '01' GROUP BY period ORDER BY label
SELECT case when t2.value > t1.value then 'rose' else 'fell' end as value from t2 join t1 using (label)
